data.transform:
function freqs(f, time) {
  const t = $moment(time);
  switch(f) {
    case 'Daily':
      return t.add(1,'day');
    case 'Weekly':
      return t.add(1,'week');
    case 'Monthly':
      return t.add(1,'month');
    case 'Quarterly':
      return t.add(.25,'year');
    case 'Bi Annual':
      return t.add(.5, 'year');
    case 'Annual':
      return t.add(1,'year');
    default:
      throw new Exception(`Frequency ${f} Not Found`);
  }
}


const start = $moment($state.context.REQUEST.DATA.startAt);
const now = $moment();
let next = $moment(start); 

do {
   next = freqs($state.context.REQUEST.DATA.frequency.id, next);
   } while (now.diff(next) > 0)

return {start,next}

(

  $payload := schedule.edges.node.(
    $startAt := nextCountAt;
    $nextCountAt := 
      frequencyId = "Daily" ? $moment(nextCountAt).add(1, 'day')
