  $L := $state.context.LOCAL;
  $N := [$L.detail[adjustment and adjustmentData.external.quantity<0]];
  $grpN := $groupBy($N, function ($v) { $v.adjustmentData.fuuz.sourceProductStrategyProcessId });
  $adjN := $each($grpN, function($v, $k) {(
    {
      "itemId":$v[0].productStrategyProcess.productStrategy.product.id, 
