function freqs(f, time) {
  const t = $moment(time);
  switch(f) {
    case 'Daily':
      return t.add(1,'day');
    case 'Weekly':
      return t.add(1,'week');
    case 'Monthly':
      return t.add(1,'month');
    case 'Quarterly':
      return t.add(.25,'year');
    case 'Bi Annual':
      return t.add(.5, 'year');
    case 'Annual':
      return t.add(1,'year');
    default:
      throw new Exception(`Frequency ${f} Not Found`);
  }
}


