query Query(
  $whereD: InventoryCountDetailWhereInput, $orderBy: [InventoryCountDetailOrderByInput!], $first: Int, $after: String,
  $whereC: InventoryCountWhereInput
) {
  detail:inventoryCountDetail(where: $whereD, orderBy: $orderBy, first: $first, after: $after) {
    edges {
      node {
        id
        approved
        complete
        adjustment
        adjustmentData
        inventoryData
        actualQuantity {
          value
          unitId
        }
        expectedQuantity {
          value
          unitId
        }
        countId
        expectedLocationId
        actualLocationId
        inventory {
          id
          product {id externalId}
          productStrategyProcess {
            productStrategy {
              product {
                id externalId
              }
            }
          }
          destinationTransactions(
            where: {
              destinationInventoryStatusId: {
                _eq: "Count"
              }
            },
            first:1,
            orderBy: {field:createdAt, direction:desc}
          ){
            edges {
              node {
                sourceInventoryStatusId
              }
            }
          }
        }
      }
    }
  },
  inventoryCount(where:$whereC){
    edges {
      node {
        id 
        schedule {
          facility {
            id externalId
          }
        }
      }
    }
  }
}

